{"command":"cd /workspace && cat > internal/yaml/scanner.go <<'EOF'
package yaml

// This file implements a YAML 1.1 token scanner. It follows the general
// structure of the classic libyaml scanner (indentation stack, simple keys,
// flow levels) so that error reporting positions behave the same way.

import (
	"fmt"
	"unicode/utf8"
)

type tokenType int

const (
	tokNone tokenType = iota
	tokStreamStart
	tokStreamEnd
	tokVersionDirective
	tokTagDirective
	tokDocumentStart
	tokDocumentEnd
	tokBlockSequenceStart
	tokBlockMappingStart
	tokBlockEnd
	tokFlowSequenceStart
	tokFlowSequenceEnd
	tokFlowMappingStart
	tokFlowMappingEnd
	tokBlockEntry
	tokFlowEntry
	tokKey
	tokValue
	tokAlias
	tokAnchor
	tokTag
	tokScalar
)

type scalarStyle int

const (
	stylePlain scalarStyle = iota
	styleSingleQuoted
	styleDoubleQuoted
	styleLiteral
	styleFolded
)

type mark struct {
	index  int
	line   int
	column int
}

type token struct {
	typ       tokenType
	start     mark
	end       mark
	value     []byte
	style     scalarStyle
	tagHandle []byte
	tagSuffix []byte
}

type simpleKey struct {
	possible    bool
	required    bool
	tokenNumber int
	mark        mark
}

type errorKind int

const (
	noError errorKind = iota
	scannerError
	parserError
)

type scanner struct {
	buf  []byte
	pos  int
	mark mark

	streamStartProduced bool
	streamEndProduced   bool

	tokens       []token
	tokensHead   int
	tokensParsed int
	tokenAvail   bool

	indent  int
	indents []int

	simpleKeyAllowed bool
	simpleKeys       []simpleKey
	flowLevel        int

	errKind     errorKind
	problem     string
	problemMark mark
	context     string
	contextMark mark
}

type scanErr struct{}

func newScanner(data []byte) *scanner {
	return &scanner{buf: data}
}

func (s *scanner) setScannerError(context string, contextMark mark, problem string) {
	s.errKind = scannerError
	s.context = context
	s.contextMark = contextMark
	s.problem = problem
	s.problemMark = s.mark
	panic(scanErr{})
}

func (s *scanner) setParserError(problem string, problemMark mark) {
	s.errKind = parserError
	s.context = ""
	s.problem = problem
	s.problemMark = problemMark
	panic(scanErr{})
}

func (s *scanner) setParserErrorContext(context string, contextMark mark, problem string, problemMark mark) {
	s.errKind = parserError
	s.context = context
	s.contextMark = contextMark
	s.problem = problem
	s.problemMark = problemMark
	panic(scanErr{})
}

// failMessage renders the error the same way the Go yaml package does:
// "line N: problem" where the line is derived from the marks.
func (s *scanner) failMessage() string {
	var line int
	if s.problemMark.line != 0 {
		line = s.problemMark.line
		if s.errKind == scannerError {
			line++
		}
	} else if s.contextMark.line != 0 {
		line = s.contextMark.line
	}
	where := ""
	if line != 0 {
		where = fmt.Sprintf("line %d: ", line)
	}
	msg := s.problem
	if msg == "" {
		msg = "unknown problem parsing YAML content"
	}
	return where + msg
}

// ---- character classification helpers ----

func (s *scanner) at(off int) byte {
	i := s.pos + off
	if i < len(s.buf) {
		return s.buf[i]
	}
	return 0
}

func (s *scanner) isZ(off int) bool { return s.pos+off >= len(s.buf) }

func (s *scanner) isBreak(off int) bool {
	c := s.at(off)
	if c == '\r' || c == '\n' {
		return true
	}
	// NEL (U+0085), LS (U+2028), PS (U+2029)
	if c == 0xC2 && s.at(off+1) == 0x85 {
		return true
	}
	if c == 0xE2 && s.at(off+1) == 0x80 && (s.at(off+2) == 0xA8 || s.at(off+2) == 0xA9) {
		return true
	}
	return false
}

func (s *scanner) isBreakZ(off int) bool { return s.isZ(off) || s.isBreak(off) }

func (s *scanner) isBlank(off int) bool {
	c := s.at(off)
	return !s.isZ(off) && (c == ' ' || c == '\t')
}

func (s *scanner) isSpace(off int) bool { return !s.isZ(off) && s.at(off) == ' ' }

func (s *scanner) isBlankZ(off int) bool { return s.isBlank(off) || s.isBreakZ(off) }

func (s *scanner) isAlpha(off int) bool {
	if s.isZ(off) {
		return false
	}
	c := s.at(off)
	return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '_' || c == '-'
}

func (s *scanner) isDigit(off int) bool {
	c := s.at(off)
	return !s.isZ(off) && c >= '0' && c <= '9'
}

func (s *scanner) isHex(off int) bool {
	c := s.at(off)
	return !s.isZ(off) && ((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F'))
}

func (s *scanner) isBOM(off int) bool {
	return s.at(off) == 0xEF && s.at(off+1) == 0xBB && s.at(off+2) == 0xBF
}

func (s *scanner) width(off int) int {
	c := s.at(off)
	switch {
	case c&0x80 == 0x00:
		return 1
	case c&0xE0 == 0xC0:
		return 2
	case c&0xF0 == 0xE0:
		return 3
	case c&0xF8 == 0xF0:
		return 4
	}
	return 1
}

// skip advances over one character.
func (s *scanner) skip() {
	w := s.width(0)
	if s.pos+w > len(s.buf) {
		w = len(s.buf) - s.pos
	}
	s.mark.index += w
	s.mark.column++
	s.pos += w
}

// skipLine advances over one line break.
func (s *scanner) skipLine() {
	if s.at(0) == '\r' && s.at(1) == '\n' {
		s.mark.index += 2
		s.mark.column = 0
		s.mark.line++
		s.pos += 2
	} else if s.isBreak(0) {
		w := s.width(0)
		s.mark.index += w
		s.mark.column = 0
		s.mark.line++
		s.pos += w
	}
}

// read copies the current character into dst and advances.
func (s *scanner) read(dst []byte) []byte {
	w := s.width(0)
	if s.pos+w > len(s.buf) {
		w = len(s.buf) - s.pos
	}
	dst = append(dst, s.buf[s.pos:s.pos+w]...)
	s.mark.index += w
	s.mark.column++
	s.pos += w
	return dst
}

// readLine copies a normalized line break into dst and advances.
func (s *scanner) readLine(dst []byte) []byte {
	c := s.at(0)
	switch {
	case c == '\r' && s.at(1) == '\n':
		dst = append(dst, '\n')
		s.pos += 2
		s.mark.index += 2
	case c == '\r' || c == '\n':
		dst = append(dst, '\n')
		s.pos++
		s.mark.index++
	case c == 0xC2 && s.at(1) == 0x85:
		dst = append(dst, '\n')
		s.pos += 2
		s.mark.index += 2
	case c == 0xE2 && s.at(1) == 0x80 && (s.at(2) == 0xA8 || s.at(2) == 0xA9):
		dst = append(dst, s.buf[s.pos:s.pos+3]...)
		s.pos += 3
		s.mark.index += 3
	default:
		return dst
	}
	s.mark.column = 0
	s.mark.line++
	return dst
}

// ---- token queue management ----

// peekToken returns the next token without consuming it.
func (s *scanner) peekToken() *token {
	if !s.tokenAvail {
		s.fetchMoreTokens()
		s.tokenAvail = true
	}
	return &s.tokens[s.tokensHead]
}

// nextToken consumes the next token.
func (s *scanner) nextToken() token {
	t := *s.peekToken()
	s.tokenAvail = false
	s.tokensHead++
	s.tokensParsed++
	if t.typ == tokStreamEnd {
		s.streamEndProduced = true
	}
	return t
}

func (s *scanner) fetchMoreTokens() {
	for {
		needMore := false
		if s.tokensHead == len(s.tokens) {
			needMore = true
		} else {
			s.staleSimpleKeys()
			for i := range s.simpleKeys {
				sk := &s.simpleKeys[i]
				if sk.possible && sk.tokenNumber == s.tokensParsed {
					needMore = true
					break
				}
			}
		}
		if !needMore {
			break
		}
		s.fetchNextToken()
	}
}

func (s *scanner) appendToken(t token) {
	s.tokens = append(s.tokens, t)
}

func (s *scanner) insertToken(pos int, t token) {
	if pos < 0 || pos > len(s.tokens)-s.tokensHead {
		s.tokens = append(s.tokens, t)
		return
	}
	idx := s.tokensHead + pos
	s.tokens = append(s.tokens, token{})
	copy(s.tokens[idx+1:], s.tokens[idx:])
	s.tokens[idx] = t
}

func (s *scanner) fetchNextToken() {
	if !s.streamStartProduced {
		s.fetchStreamStart()
		return
	}
	s.scanToNextToken()
	s.staleSimpleKeys()
	s.unrollIndent(s.mark.column)

	if s.isZ(0) {
		s.fetchStreamEnd()
		return
	}
	c := s.at(0)
	if s.mark.column == 0 && c == '%' {
		s.fetchDirective()
		return
	}
	if s.mark.column == 0 && c == '-' && s.at(1) == '-' && s.at(2) == '-' && s.isBlankZ(3) {
		s.fetchDocumentIndicator(tokDocumentStart)
		return
	}
	if s.mark.column == 0 && c == '.' && s.at(1) == '.' && s.at(2) == '.' && s.isBlankZ(3) {
		s.fetchDocumentIndicator(tokDocumentEnd)
		return
	}
	switch c {
	case '[':
		s.fetchFlowCollectionStart(tokFlowSequenceStart)
		return
	case '{':
		s.fetchFlowCollectionStart(tokFlowMappingStart)
		return
	case ']':
		s.fetchFlowCollectionEnd(tokFlowSequenceEnd)
		return
	case '}':
		s.fetchFlowCollectionEnd(tokFlowMappingEnd)
		return
	case ',':
		s.fetchFlowEntry()
		return
	}
	if c == '-' && s.isBlankZ(1) {
		s.fetchBlockEntry()
		return
	}
	if c == '?' && (s.flowLevel > 0 || s.isBlankZ(1)) {
		s.fetchKey()
		return
	}
	if c == ':' && (s.flowLevel > 0 || s.isBlankZ(1)) {
		s.fetchValue()
		return
	}
	switch c {
	case '*':
		s.fetchAnchor(tokAlias)
		return
	case '&':
		s.fetchAnchor(tokAnchor)
		return
	case '!':
		s.fetchTag()
		return
	case '|':
		if s.flowLevel == 0 {
			s.fetchBlockScalar(true)
			return
		}
	case '>':
		if s.flowLevel == 0 {
			s.fetchBlockScalar(false)
			return
		}
	case '\'':
		s.fetchFlowScalar(true)
		return
	case '"':
		s.fetchFlowScalar(false)
		return
	}
	isIndicator := false
	switch c {
	case '-', '?', ':', ',', '[', ']', '{', '}', '#', '&', '*', '!', '|', '>', '\'', '"', '%', '@', '`':
		isIndicator = true
	}
	if !(s.isBlankZ(0) || isIndicator) ||
		(c == '-' && !s.isBlank(1)) ||
		(s.flowLevel == 0 && (c == '?' || c == ':') && !s.isBlankZ(1)) {
		s.fetchPlainScalar()
		return
	}
	s.setScannerError("while scanning for the next token", s.mark, "found character that cannot start any token")
}

func (s *scanner) staleSimpleKeys() {
	for i := range s.simpleKeys {
		sk := &s.simpleKeys[i]
		if sk.possible && (sk.mark.line < s.mark.line || sk.mark.index+1024 < s.mark.index) {
			if sk.required {
				s.setScannerError("while scanning a simple key", sk.mark, "could not find expected ':'")
			}
			sk.possible = false
		}
	}
}

func (s *scanner) saveSimpleKey() {
	required := s.flowLevel == 0 && s.indent == s.mark.column
	if s.simpleKeyAllowed {
		sk := simpleKey{
			possible:    true,
			required:    required,
			tokenNumber: s.tokensParsed + (len(s.tokens) - s.tokensHead),
			mark:        s.mark,
		}
		s.removeSimpleKey()
		s.simpleKeys[len(s.simpleKeys)-1] = sk
	}
}

func (s *scanner) removeSimpleKey() {
	sk := &s.simpleKeys[len(s.simpleKeys)-1]
	if sk.possible && sk.required {
		s.setScannerError("while scanning a simple key", sk.mark, "could not find expected ':'")
	}
	sk.possible = false
}

func (s *scanner) increaseFlowLevel() {
	s.simpleKeys = append(s.simpleKeys, simpleKey{})
	s.flowLevel++
}

func (s *scanner) decreaseFlowLevel() {
	if s.flowLevel > 0 {
		s.flowLevel--
		s.simpleKeys = s.simpleKeys[:len(s.simpleKeys)-1]
	}
}

func (s *scanner) rollIndent(column, number int, typ tokenType, m mark) {
	if s.flowLevel > 0 {
		return
	}
	if s.indent < column {
		s.indents = append(s.indents, s.indent)
		s.indent = column
		t := token{typ: typ, start: m, end: m}
		if number == -1 {
			s.appendToken(t)
		} else {
			s.insertToken(number-s.tokensParsed, t)
		}
	}
}

func (s *scanner) unrollIndent(column int) {
	if s.flowLevel > 0 {
		return
	}
	for s.indent > column {
		s.appendToken(token{typ: tokBlockEnd, start: s.mark, end: s.mark})
		s.indent = s.indents[len(s.indents)-1]
		s.indents = s.indents[:len(s.indents)-1]
	}
}

func (s *scanner) fetchStreamStart() {
	s.indent = -1
	s.simpleKeys = append(s.simpleKeys, simpleKey{})
	s.simpleKeyAllowed = true
	s.streamStartProduced = true
	s.appendToken(token{typ: tokStreamStart, start: s.mark, end: s.mark})
}

func (s *scanner) fetchStreamEnd() {
	// Force a new line.
	if s.mark.column != 0 {
		s.mark.column = 0
		s.mark.line++
	}
	s.unrollIndent(-1)
	s.removeSimpleKey()
	s.simpleKeyAllowed = false
	s.appendToken(token{typ: tokStreamEnd, start: s.mark, end: s.mark})
}

func (s *scanner) fetchDirective() {
	s.unrollIndent(-1)
	s.removeSimpleKey()
	s.simpleKeyAllowed = false
	start := s.mark
	s.skip() // '%'
	var name []byte
	for s.isAlpha(0) {
		name = s.read(name)
	}
	if len(name) == 0 {
		s.setScannerError("while scanning a directive", start, "could not find expected directive name")
	}
	if !s.isBlankZ(0) {
		s.setScannerError("while scanning a directive", start, "found unexpected non-alphabetical character")
	}
	typ := tokVersionDirective
	if string(name) == "TAG" {
		typ = tokTagDirective
	} else if string(name) != "YAML" {
		s.setScannerError("while scanning a directive", start, "found unknown directive name")
	}
	// Skip the rest of the directive line (we do not interpret directives).
	for !s.isBreakZ(0) {
		s.skip()
	}
	s.appendToken(token{typ: typ, start: start, end: s.mark})
}

func (s *scanner) fetchDocumentIndicator(typ tokenType) {
	s.unrollIndent(-1)
	s.removeSimpleKey()
	s.simpleKeyAllowed = false
	start := s.mark
	s.skip()
	s.skip()
	s.skip()
	s.appendToken(token{typ: typ, start: start, end: s.mark})
}

func (s *scanner) fetchFlowCollectionStart(typ tokenType) {
	s.saveSimpleKey()
	s.increaseFlowLevel()
	s.simpleKeyAllowed = true
	start := s.mark
	s.skip()
	s.appendToken(token{typ: typ, start: start, end: s.mark})
}

func (s *scanner) fetchFlowCollectionEnd(typ tokenType) {
	s.removeSimpleKey()
	s.decreaseFlowLevel()
	s.simpleKeyAllowed = false
	start := s.mark
	s.skip()
	s.appendToken(token{typ: typ, start: start, end: s.mark})
}

func (s *scanner) fetchFlowEntry() {
	s.removeSimpleKey()
	s.simpleKeyAllowed = true
	start := s.mark
	s.skip()
	s.appendToken(token{typ: tokFlowEntry, start: start, end: s.mark})
}

func (s *scanner) fetchBlockEntry() {
	if s.flowLevel == 0 {
		if !s.simpleKeyAllowed {
			s.setScannerError("", s.mark, "block sequence entries are not allowed in this context")
		}
		s.rollIndent(s.mark.column, -1, tokBlockSequenceStart, s.mark)
	}
	s.removeSimpleKey()
	s.simpleKeyAllowed = true
	start := s.mark
	s.skip()
	s.appendToken(token{typ: tokBlockEntry, start: start, end: s.mark})
}

func (s *scanner) fetchKey() {
	if s.flowLevel == 0 {
		if !s.simpleKeyAllowed {
			s.setScannerError("", s.mark, "mapping keys are not allowed in this context")
		}
		s.rollIndent(s.mark.column, -1, tokBlockMappingStart, s.mark)
	}
	s.removeSimpleKey()
	s.simpleKeyAllowed = s.flowLevel == 0
	start := s.mark
	s.skip()
	s.appendToken(token{typ: tokKey, start: start, end: s.mark})
}

func (s *scanner) fetchValue() {
	sk := &s.simpleKeys[len(s.simpleKeys)-1]
	if sk.possible {
		s.insertToken(sk.tokenNumber-s.tokensParsed, token{typ: tokKey, start: sk.mark, end: sk.mark})
		s.rollIndent(sk.mark.column, sk.tokenNumber, tokBlockMappingStart, sk.mark)
		sk.possible = false
		s.simpleKeyAllowed = false
	} else {
		if s.flowLevel == 0 {
			if !s.simpleKeyAllowed {
				s.setScannerError("", s.mark, "mapping values are not allowed in this context")
			}
			s.rollIndent(s.mark.column, -1, tokBlockMappingStart, s.mark)
		}
		s.simpleKeyAllowed = s.flowLevel == 0
	}
	start := s.mark
	s.skip()
	s.appendToken(token{typ: tokValue, start: start, end: s.mark})
}

func (s *scanner) fetchAnchor(typ tokenType) {
	s.saveSimpleKey()
	s.simpleKeyAllowed = false
	start := s.mark
	s.skip()
	var value []byte
	for s.isAlpha(0) {
		value = s.read(value)
	}
	c := s.at(0)
	if len(value) == 0 || !(s.isBlankZ(0) || c == '?' || c == ':' || c == ',' || c == ']' || c == '}' || c == '%' || c == '@' || c == '`') {
		ctx := "while scanning an anchor"
		if typ == tokAlias {
			ctx = "while scanning an alias"
		}
		s.setScannerError(ctx, start, "did not find expected alphabetic or numeric character")
	}
	s.appendToken(token{typ: typ, start: start, end: s.mark, value: value})
}

func (s *scanner) fetchTag() {
	s.saveSimpleKey()
	s.simpleKeyAllowed = false
	start := s.mark
	var handle, suffix []byte
	if s.at(1) == '<' {
		s.skip()
		s.skip()
		for !s.isZ(0) && s.at(0) != '>' && !s.isBlankZ(0) {
			suffix = s.read(suffix)
		}
		if s.at(0) != '>' {
			s.setScannerError("while scanning a tag", start, "did not find the expected '>'")
		}
		s.skip()
	} else {
		// Scan the handle: '!' followed by alpha chars and optionally '!'.
		handle = s.read(handle) // '!'
		for s.isAlpha(0) {
			handle = s.read(handle)
		}
		if s.at(0) == '!' {
			handle = s.read(handle)
		} else {
			// Not a real handle: everything after the first '!' is the suffix.
			if len(handle) > 1 {
				suffix = append(suffix, handle[1:]...)
				handle = handle[:1]
			}
		}
		for !s.isBlankZ(0) {
			c := s.at(0)
			if c == ',' || c == ']' || c == '}' {
				if s.flowLevel > 0 {
					break
				}
			}
			suffix = s.read(suffix)
		}
		if len(handle) == 1 && len(suffix) == 0 {
			// A lone '!' is the non-specific tag.
		}
	}
	if !s.isBlankZ(0) && !(s.flowLevel > 0 && (s.at(0) == ',' || s.at(0) == ']' || s.at(0) == '}')) {
		s.setScannerError("while scanning a tag", start, "did not find expected whitespace or line break")
	}
	s.appendToken(token{typ: tokTag, start: start, end: s.mark, tagHandle: handle, tagSuffix: suffix})
}

func (s *scanner) fetchBlockScalar(literal bool) {
	s.removeSimpleKey()
	s.simpleKeyAllowed = true
	s.scanBlockScalar(literal)
}

func (s *scanner) fetchFlowScalar(single bool) {
	s.saveSimpleKey()
	s.simpleKeyAllowed = false
	s.scanFlowScalar(single)
}

func (s *scanner) fetchPlainScalar() {
	s.saveSimpleKey()
	s.simpleKeyAllowed = false
	s.scanPlainScalar()
}

func (s *scanner) scanToNextToken() {
	for {
		if s.mark.column == 0 && s.isBOM(0) {
			s.skip()
			s.skip()
			s.skip()
		}
		for s.at(0) == ' ' && !s.isZ(0) || ((s.flowLevel > 0 || !s.simpleKeyAllowed) && s.at(0) == '\t' && !s.isZ(0)) {
			s.skip()
		}
		if s.at(0) == '#' && !s.isZ(0) {
			for !s.isBreakZ(0) {
				s.skip()
			}
		}
		if s.isBreak(0) {
			s.skipLine()
			if s.flowLevel == 0 {
				s.simpleKeyAllowed = true
			}
		} else {
			break
		}
	}
}

func (s *scanner) scanBlockScalarBreaks(indent *int, breaks []byte, start mark, end *mark) []byte {
	maxIndent := 0
	*end = s.mark
	for {
		for (*indent == 0 || s.mark.column < *indent) && s.isSpace(0) {
			s.skip()
		}
		if s.mark.column > maxIndent {
			maxIndent = s.mark.column
		}
		if (*indent == 0 || s.mark.column < *indent) && s.at(0) == '\t' && !s.isZ(0) {
			s.setScannerError("while scanning a block scalar", start, "found a tab character where an indentation space is expected")
		}
		if !s.isBreak(0) {
			break
		}
		breaks = s.readLine(breaks)
		*end = s.mark
	}
	if *indent == 0 {
		*indent = maxIndent
		if *indent < s.indent+1 {
			*indent = s.indent + 1
		}
		if *indent < 1 {
			*indent = 1
		}
	}
	return breaks
}

func (s *scanner) scanBlockScalar(literal bool) {
	start := s.mark
	s.skip() // '|' or '>'
	chomping := 0
	increment := 0
	if s.at(0) == '+' || s.at(0) == '-' {
		if s.at(0) == '+' {
			chomping = 1
		} else {
			chomping = -1
		}
		s.skip()
		if s.isDigit(0) {
			if s.at(0) == '0' {
				s.setScannerError("while scanning a block scalar", start, "found an indentation indicator equal to 0")
			}
			increment = int(s.at(0) - '0')
			s.skip()
		}
	} else if s.isDigit(0) {
		if s.at(0) == '0' {
			s.setScannerError("while scanning a block scalar", start, "found an indentation indicator equal to 0")
		}
		increment = int(s.at(0) - '0')
		s.skip()
		if s.at(0) == '+' || s.at(0) == '-' {
			if s.at(0) == '+' {
				chomping = 1
			} else {
				chomping = -1
			}
			s.skip()
		}
	}
	for s.isBlank(0) {
		s.skip()
	}
	if s.at(0) == '#' && !s.isZ(0) {
		for !s.isBreakZ(0) {
			s.skip()
		}
	}
	if !s.isBreakZ(0) {
		s.setScannerError("while scanning a block scalar", start, "did not find expected comment or line break")
	}
	if s.isBreak(0) {
		s.skipLine()
	}
	end := s.mark
	indent := 0
	if increment > 0 {
		if s.indent >= 0 {
			indent = s.indent + increment
		} else {
			indent = increment
		}
	}
	var value, leadingBreak, trailingBreaks []byte
	trailingBreaks = s.scanBlockScalarBreaks(&indent, trailingBreaks, start, &end)
	leadingBlank := false
	trailingBlank := false
	for s.mark.column == indent && !s.isZ(0) {
		trailingBlank = s.isBlank(0)
		if !literal && len(leadingBreak) > 0 && leadingBreak[0] == '\n' && !leadingBlank && !trailingBlank {
			if len(trailingBreaks) == 0 {
				value = append(value, ' ')
			}
			leadingBreak = leadingBreak[:0]
		} else {
			value = append(value, leadingBreak...)
			leadingBreak = leadingBreak[:0]
		}
		value = append(value, trailingBreaks...)
		trailingBreaks = trailingBreaks[:0]
		leadingBlank = s.isBlank(0)
		for !s.isBreakZ(0) {
			value = s.read(value)
		}
		if s.isZ(0) {
			break
		}
		leadingBreak = s.readLine(leadingBreak)
		trailingBreaks = s.scanBlockScalarBreaks(&indent, trailingBreaks, start, &end)
	}
	if chomping != -1 {
		value = append(value, leadingBreak...)
	}
	if chomping == 1 {
		value = append(value, trailingBreaks...)
	}
	st := styleFolded
	if literal {
		st = styleLiteral
	}
	s.appendToken(token{typ: tokScalar, start: start, end: end, value: value, style: st})
}

func (s *scanner) scanFlowScalar(single bool) {
	start := s.mark
	s.skip() // the quote
	var value, leadingBreak, trailingBreaks, whitespaces []byte
	for {
		if s.mark.column == 0 &&
			((s.at(0) == '-' && s.at(1) == '-' && s.at(2) == '-') || (s.at(0) == '.' && s.at(1) == '.' && s.at(2) == '.')) &&
			s.isBlankZ(3) {
			s.setScannerError("while scanning a quoted scalar", start, "found unexpected document indicator")
		}
		if s.isZ(0) {
			s.setScannerError("while scanning a quoted scalar", start, "found unexpected end of stream")
		}
		leadingBlanks := false
		for !s.isBlankZ(0) {
			c := s.at(0)
			if single && c == '\'' && s.at(1) == '\'' {
				value = append(value, '\'')
				s.skip()
				s.skip()
			} else if c == '\'' && single || c == '"' && !single {
				break
			} else if !single && c == '\\' && s.isBreak(1) {
				s.skip()
				s.skipLine()
				leadingBlanks = true
				break
			} else if !single && c == '\\' {
				codeLength := 0
				switch s.at(1) {
				case '0':
					value = append(value, 0)
				case 'a':
					value = append(value, 7)
				case 'b':
					value = append(value, 8)
				case 't', '\t':
					value = append(value, 9)
				case 'n':
					value = append(value, 10)
				case 'v':
					value = append(value, 11)
				case 'f':
					value = append(value, 12)
				case 'r':
					value = append(value, 13)
				case 'e':
					value = append(value, 27)
				case ' ':
					value = append(value, ' ')
				case '"':
					value = append(value, '"')
				case '\'':
					value = append(value, '\'')
				case '\\':
					value = append(value, '\\')
				case 'N':
					value = append(value, 0xC2, 0x85)
				case '_':
					value = append(value, 0xC2, 0xA0)
				case 'L':
					value = append(value, 0xE2, 0x80, 0xA8)
				case 'P':
					value = append(value, 0xE2, 0x80, 0xA9)
				case 'x':
					codeLength = 2
				case 'u':
					codeLength = 4
				case 'U':
					codeLength = 8
				default:
					s.setScannerError("while parsing a quoted scalar", start, "found unknown escape character")
				}
				s.skip()
				s.skip()
				if codeLength > 0 {
					var v rune
					for k := 0; k < codeLength; k++ {
						if !s.isHex(k) {
							s.setScannerError("while parsing a quoted scalar", start, "did not find expected hexdecimal number")
						}
						h := s.at(k)
						var d rune
						switch {
						case h >= '0' && h <= '9':
							d = rune(h - '0')
						case h >= 'a' && h <= 'f':
							d = rune(h-'a') + 10
						default:
							d = rune(h-'A') + 10
						}
						v = v<<4 + d
					}
					if (v >= 0xD800 && v <= 0xDFFF) || v > 0x10FFFF {
						s.setScannerError("while parsing a quoted scalar", start, "found invalid Unicode character escape code")
					}
					var tmp [4]byte
					n := utf8.EncodeRune(tmp[:], v)
					value = append(value, tmp[:n]...)
					for k := 0; k < codeLength; k++ {
						s.skip()
					}
				}
			} else {
				value = s.read(value)
			}
		}
		if s.at(0) == '\'' && single || s.at(0) == '"' && !single {
			if !s.isZ(0) {
				break
			}
		}
		if s.isZ(0) {
			s.setScannerError("while scanning a quoted scalar", start, "found unexpected end of stream")
		}
		for s.isBlank(0) || s.isBreak(0) {
			if s.isBlank(0) {
				if !leadingBlanks {
					whitespaces = s.read(whitespaces)
				} else {
					s.skip()
				}
			} else {
				if !leadingBlanks {
					whitespaces = whitespaces[:0]
					leadingBreak = s.readLine(leadingBreak)
					leadingBlanks = true
				} else {
					trailingBreaks = s.readLine(trailingBreaks)
				}
			}
		}
		if leadingBlanks {
			if len(leadingBreak) > 0 && leadingBreak[0] == '\n' {
				if len(trailingBreaks) == 0 {
					value = append(value, ' ')
				} else {
					value = append(value, trailingBreaks...)
				}
			} else {
				value = append(value, leadingBreak...)
				value = append(value, trailingBreaks...)
			}
			leadingBreak = leadingBreak[:0]
			trailingBreaks = trailingBreaks[:0]
		} else {
			value = append(value, whitespaces...)
			whitespaces = whitespaces[:0]
		}
	}
	s.skip() // closing quote
	st := styleDoubleQuoted
	if single {
		st = styleSingleQuoted
	}
	s.appendToken(token{typ: tokScalar, start: start, end: s.mark, value: value, style: st})
}

func (s *scanner) scanPlainScalar() {
	start := s.mark
	end := s.mark
	indent := s.indent + 1
	var value, leadingBreak, trailingBreaks, whitespaces []byte
	leadingBlanks := false
	for {
		if s.mark.column == 0 &&
			((s.at(0) == '-' && s.at(1) == '-' && s.at(2) == '-') || (s.at(0) == '.' && s.at(1) == '.' && s.at(2) == '.')) &&
			s.isBlankZ(3) {
			break
		}
		if s.at(0) == '#' && !s.isZ(0) {
			break
		}
		for !s.isBlankZ(0) {
			c := s.at(0)
			if s.flowLevel > 0 && c == ':' {
				n := s.at(1)
				if n == ',' || n == '?' || n == '[' || n == ']' || n == '{' || n == '}' {
					s.setScannerError("while scanning a plain scalar", start, "found unexpected ':'")
				}
			}
			if (c == ':' && s.isBlankZ(1)) ||
				(s.flowLevel > 0 && (c == ',' || c == '?' || c == '[' || c == ']' || c == '{' || c == '}')) {
				break
			}
			if leadingBlanks || len(whitespaces) > 0 {
				if leadingBlanks {
					if len(leadingBreak) > 0 && leadingBreak[0] == '\n' {
						if len(trailingBreaks) == 0 {
							value = append(value, ' ')
						} else {
							value = append(value, trailingBreaks...)
						}
					} else {
						value = append(value, leadingBreak...)
						value = append(value, trailingBreaks...)
					}
					leadingBreak = leadingBreak[:0]
					trailingBreaks = trailingBreaks[:0]
					leadingBlanks = false
				} else {
					value = append(value, whitespaces...)
					whitespaces = whitespaces[:0]
				}
			}
			value = s.read(value)
			end = s.mark
		}
		if !(s.isBlank(0) || s.isBreak(0)) {
			break
		}
		for s.isBlank(0) || s.isBreak(0) {
			if s.isBlank(0) {
				if leadingBlanks && s.mark.column < indent && s.at(0) == '\t' {
					s.setScannerError("while scanning a plain scalar", start, "found a tab character that violates indentation")
				}
				if !leadingBlanks {
					whitespaces = s.read(whitespaces)
				} else {
					s.skip()
				}
			} else {
				if !leadingBlanks {
					whitespaces = whitespaces[:0]
					leadingBreak = s.readLine(leadingBreak)
					leadingBlanks = true
				} else {
					trailingBreaks = s.readLine(trailingBreaks)
				}
			}
		}
		if s.flowLevel == 0 && s.mark.column < indent {
			break
		}
	}
	s.appendToken(token{typ: tokScalar, start: start, end: end, value: value, style: stylePlain})
	if leadingBlanks {
		s.simpleKeyAllowed = true
	}
}
EOF
