{"command":"cd /workspace && cat > internal/yaml/parser.go <<'EOF'
package yaml

// The parser consumes tokens from the scanner and builds a node tree for a
// single document, following the grammar used by libyaml-style parsers.

type nodeKind int

const (
	documentNode nodeKind = iota
	mappingNode
	sequenceNode
	scalarNode
	aliasNode
)

type node struct {
	kind     nodeKind
	line     int // 0-based
	column   int
	tag      string
	value    string
	implicit bool
	children []*node
	anchors  map[string]*node
}

type parser struct {
	s   *scanner
	doc *node
}

const (
	tagPrefix     = "tag:yaml.org,2002:"
	nullTag       = tagPrefix + "null"
	boolTag       = tagPrefix + "bool"
	strTag        = tagPrefix + "str"
	intTag        = tagPrefix + "int"
	floatTag      = tagPrefix + "float"
	timestampTag  = tagPrefix + "timestamp"
	seqTag        = tagPrefix + "seq"
	mapTag        = tagPrefix + "map"
	binaryTag     = tagPrefix + "binary"
	mergeTag      = tagPrefix + "merge"
)

func shortTag(tag string) string {
	if len(tag) > len(tagPrefix) && tag[:len(tagPrefix)] == tagPrefix {
		return "!!" + tag[len(tagPrefix):]
	}
	return tag
}

func longTag(tag string) string {
	if len(tag) >= 2 && tag[:2] == "!!" {
		return tagPrefix + tag[2:]
	}
	return tag
}

func (p *parser) newNode(kind nodeKind, m mark) *node {
	return &node{kind: kind, line: m.line, column: m.column}
}

func (p *parser) anchor(n *node, anchor []byte) {
	if len(anchor) > 0 && p.doc != nil {
		p.doc.anchors[string(anchor)] = n
	}
}

// parseDocument parses the first document in the stream and returns its
// root node, or nil if the stream is empty.
func (p *parser) parseDocument() *node {
	s := p.s
	t := s.nextToken()
	if t.typ != tokStreamStart {
		s.setParserError("did not find expected <stream-start>", t.start)
	}
	t = *s.peekToken()
	if t.typ == tokStreamEnd {
		return nil
	}
	doc := p.newNode(documentNode, t.start)
	doc.anchors = make(map[string]*node)
	p.doc = doc

	implicit := true
	if t.typ == tokVersionDirective || t.typ == tokTagDirective || t.typ == tokDocumentStart {
		implicit = false
		for t.typ == tokVersionDirective || t.typ == tokTagDirective {
			s.nextToken()
			t = *s.peekToken()
		}
		if t.typ != tokDocumentStart {
			s.setParserError("did not find expected <document start>", t.start)
		}
		s.nextToken()
		t = *s.peekToken()
	}

	var root *node
	if implicit {
		root = p.parseNode(true, false)
	} else {
		if t.typ == tokVersionDirective || t.typ == tokTagDirective || t.typ == tokDocumentStart || t.typ == tokDocumentEnd || t.typ == tokStreamEnd {
			root = p.emptyScalar(t.start)
		} else {
			root = p.parseNode(true, false)
		}
	}
	doc.children = append(doc.children, root)

	// Document end (implicit or explicit).
	t = *s.peekToken()
	if t.typ == tokDocumentEnd {
		s.nextToken()
	} else if implicit {
		// After an implicit document the only allowed continuations are
		// another document start or the end of stream.
		if t.typ != tokStreamEnd && t.typ != tokDocumentStart && t.typ != tokVersionDirective && t.typ != tokTagDirective {
			s.setParserError("did not find expected <document start>", t.start)
		}
	}
	return doc
}

func (p *parser) emptyScalar(m mark) *node {
	n := p.newNode(scalarNode, m)
	n.implicit = true
	n.value = ""
	return n
}

func (p *parser) parseNode(block, indentlessSequence bool) *node {
	s := p.s
	t := *s.peekToken()
	if t.typ == tokAlias {
		s.nextToken()
		n := p.newNode(aliasNode, t.start)
		n.value = string(t.value)
		return n
	}
	start := t.start
	var anchor []byte
	var tagHandle, tagSuffix []byte
	hasTag := false
	tagMark := t.start
	if t.typ == tokAnchor {
		s.nextToken()
		anchor = t.value
		t = *s.peekToken()
		if t.typ == tokTag {
			s.nextToken()
			hasTag = true
			tagHandle, tagSuffix = t.tagHandle, t.tagSuffix
			tagMark = t.start
			t = *s.peekToken()
		}
	} else if t.typ == tokTag {
		s.nextToken()
		hasTag = true
		tagHandle, tagSuffix = t.tagHandle, t.tagSuffix
		tagMark = t.start
		t = *s.peekToken()
		if t.typ == tokAnchor {
			s.nextToken()
			anchor = t.value
			t = *s.peekToken()
		}
	}
	tag := ""
	if hasTag {
		switch string(tagHandle) {
		case "":
			tag = string(tagSuffix)
		case "!!":
			tag = tagPrefix + string(tagSuffix)
		case "!":
			tag = "!" + string(tagSuffix)
		default:
			s.setParserErrorContext("while parsing a node", start, "found undefined tag handle", tagMark)
		}
	}
	_ = tagMark

	if indentlessSequence && t.typ == tokBlockEntry {
		n := p.newNode(sequenceNode, t.start)
		n.tag = tag
		p.anchor(n, anchor)
		p.parseIndentlessSequence(n)
		return n
	}
	switch t.typ {
	case tokScalar:
		s.nextToken()
		n := p.newNode(scalarNode, t.start)
		n.value = string(t.value)
		n.tag = tag
		if t.style == stylePlain && !hasTag {
			n.implicit = true
		}
		p.anchor(n, anchor)
		return n
	case tokFlowSequenceStart:
		n := p.newNode(sequenceNode, t.start)
		n.tag = tag
		p.anchor(n, anchor)
		p.parseFlowSequence(n)
		return n
	case tokFlowMappingStart:
		n := p.newNode(mappingNode, t.start)
		n.tag = tag
		p.anchor(n, anchor)
		p.parseFlowMapping(n)
		return n
	case tokBlockSequenceStart:
		if block {
			n := p.newNode(sequenceNode, t.start)
			n.tag = tag
			p.anchor(n, anchor)
			p.parseBlockSequence(n)
			return n
		}
	case tokBlockMappingStart:
		if block {
			n := p.newNode(mappingNode, t.start)
			n.tag = tag
			p.anchor(n, anchor)
			p.parseBlockMapping(n)
			return n
		}
	}
	if len(anchor) > 0 || hasTag {
		n := p.newNode(scalarNode, start)
		n.tag = tag
		n.implicit = !hasTag
		p.anchor(n, anchor)
		return n
	}
	ctx := "while parsing a flow node"
	if block {
		ctx = "while parsing a block node"
	}
	s.setParserErrorContext(ctx, start, "did not find expected node content", t.start)
	return nil
}

func (p *parser) parseBlockSequence(n *node) {
	s := p.s
	startTok := s.nextToken() // BLOCK-SEQUENCE-START
	for {
		t := *s.peekToken()
		if t.typ == tokBlockEntry {
			s.nextToken()
			nt := *s.peekToken()
			if nt.typ != tokBlockEntry && nt.typ != tokBlockEnd {
				n.children = append(n.children, p.parseNode(true, false))
			} else {
				n.children = append(n.children, p.emptyScalar(t.end))
			}
			continue
		}
		if t.typ == tokBlockEnd {
			s.nextToken()
			return
		}
		s.setParserErrorContext("while parsing a block collection", startTok.start, "did not find expected '-' indicator", t.start)
	}
}

func (p *parser) parseIndentlessSequence(n *node) {
	s := p.s
	for {
		t := *s.peekToken()
		if t.typ != tokBlockEntry {
			return
		}
		s.nextToken()
		nt := *s.peekToken()
		if nt.typ != tokBlockEntry && nt.typ != tokKey && nt.typ != tokValue && nt.typ != tokBlockEnd {
			n.children = append(n.children, p.parseNode(true, false))
		} else {
			n.children = append(n.children, p.emptyScalar(t.end))
		}
	}
}

func (p *parser) parseBlockMapping(n *node) {
	s := p.s
	startTok := s.nextToken() // BLOCK-MAPPING-START
	for {
		t := *s.peekToken()
		if t.typ == tokKey {
			s.nextToken()
			nt := *s.peekToken()
			if nt.typ != tokKey && nt.typ != tokValue && nt.typ != tokBlockEnd {
				n.children = append(n.children, p.parseNode(true, true))
			} else {
				n.children = append(n.children, p.emptyScalar(t.end))
			}
		} else if t.typ == tokBlockEnd {
			s.nextToken()
			return
		} else {
			s.setParserErrorContext("while parsing a block mapping", startTok.start, "did not find expected key", t.start)
		}
		// value
		t = *s.peekToken()
		if t.typ == tokValue {
			s.nextToken()
			nt := *s.peekToken()
			if nt.typ != tokKey && nt.typ != tokValue && nt.typ != tokBlockEnd {
				n.children = append(n.children, p.parseNode(true, true))
			} else {
				n.children = append(n.children, p.emptyScalar(t.end))
			}
		} else {
			n.children = append(n.children, p.emptyScalar(t.start))
		}
	}
}

func (p *parser) parseFlowSequence(n *node) {
	s := p.s
	startTok := s.nextToken() // '['
	first := true
	for {
		t := *s.peekToken()
		if t.typ != tokFlowSequenceEnd {
			if !first {
				if t.typ == tokFlowEntry {
					s.nextToken()
					t = *s.peekToken()
				} else {
					s.setParserErrorContext("while parsing a flow sequence", startTok.start, "did not find expected ',' or ']'", t.start)
				}
			}
			if t.typ == tokKey {
				s.nextToken()
				pair := p.newNode(mappingNode, t.start)
				nt := *s.peekToken()
				if nt.typ != tokValue && nt.typ != tokFlowEntry && nt.typ != tokFlowSequenceEnd {
					pair.children = append(pair.children, p.parseNode(false, false))
				} else {
					pair.children = append(pair.children, p.emptyScalar(t.end))
				}
				vt := *s.peekToken()
				if vt.typ == tokValue {
					s.nextToken()
					nt = *s.peekToken()
					if nt.typ != tokFlowEntry && nt.typ != tokFlowSequenceEnd {
						pair.children = append(pair.children, p.parseNode(false, false))
					} else {
						pair.children = append(pair.children, p.emptyScalar(vt.end))
					}
				} else {
					pair.children = append(pair.children, p.emptyScalar(vt.start))
				}
				n.children = append(n.children, pair)
				first = false
				continue
			} else if t.typ != tokFlowSequenceEnd {
				n.children = append(n.children, p.parseNode(false, false))
				first = false
				continue
			}
		}
		s.nextToken() // ']'
		return
	}
}

func (p *parser) parseFlowMapping(n *node) {
	s := p.s
	startTok := s.nextToken() // '{'
	first := true
	for {
		t := *s.peekToken()
		if t.typ != tokFlowMappingEnd {
			if !first {
				if t.typ == tokFlowEntry {
					s.nextToken()
					t = *s.peekToken()
				} else {
					s.setParserErrorContext("while parsing a flow mapping", startTok.start, "did not find expected ',' or '}'", t.start)
				}
			}
			if t.typ == tokKey {
				s.nextToken()
				nt := *s.peekToken()
				if nt.typ != tokValue && nt.typ != tokFlowEntry && nt.typ != tokFlowMappingEnd {
					n.children = append(n.children, p.parseNode(false, false))
				} else {
					n.children = append(n.children, p.emptyScalar(t.end))
				}
				vt := *s.peekToken()
				if vt.typ == tokValue {
					s.nextToken()
					nt = *s.peekToken()
					if nt.typ != tokFlowEntry && nt.typ != tokFlowMappingEnd {
						n.children = append(n.children, p.parseNode(false, false))
					} else {
						n.children = append(n.children, p.emptyScalar(vt.end))
					}
				} else {
					n.children = append(n.children, p.emptyScalar(vt.start))
				}
				first = false
				continue
			} else if t.typ != tokFlowMappingEnd {
				// A key without the '?' indicator and without ':'.
				n.children = append(n.children, p.parseNode(false, false))
				vt := *s.peekToken()
				n.children = append(n.children, p.emptyScalar(vt.start))
				first = false
				continue
			}
		}
		s.nextToken() // '}'
		return
	}
}
