type Color struct {
	kind    colorKind
	basic   int // 0-7 for normal colors, 8-15 for bright ones
	palette int
	r, g, b int
}

var errInvalidColor = errors.New("invalid format")

var basicColorNames = map[string]int{
	"black":        0,
	"red":          1,
	"green":        2,
	"yellow":       3,
	"blue":         4,
	"magenta":      5,
	"cyan":         6,
	"white":        7,
	"lightBlack":   8,
	"lightRed":     9,
	"lightGreen":   10,
	"lightYellow":  11,
	"lightBlue":    12,
	"lightMagenta": 13,
	"lightCyan":    14,
	"lightWhite":   15,
}

var (
	hexColorRe     = regexp.MustCompile(`^#([0-9a-fA-F]{2})([0-9a-fA-F]{2})([0-9a-fA-F]{2})$`)
	rgbColorRe     = regexp.MustCompile(`^(?i:rgb)\(([0-9]+|0[xX][0-9a-fA-F]+), *([0-9]+|0[xX][0-9a-fA-F]+), *([0-9]+|0[xX][0-9a-fA-F]+)\)$`)
	decimalRe      = regexp.MustCompile(`^[0-9]+$`)
	hexNumberRe    = regexp.MustCompile(`^0[xX][0-9a-fA-F]+$`)
)

func parseComponent(s string) (int, bool) {
	var v uint64
	var err error
	if hexNumberRe.MatchString(s) {
		v, err = strconv.ParseUint(s[2:], 16, 32)
	} else if decimalRe.MatchString(s) {
		v, err = strconv.ParseUint(s, 10, 32)
	} else {
		return 0, false
	}
	if err != nil || v > 255 {
		return 0, false
	}
	return int(v), true
}

// ParseColor parses a color specification.
func ParseColor(s string) (Color, error) {
	if s == "" || s == "default" {
		return Color{}, nil
	}
	if v, ok := basicColorNames[s]; ok {
		return Color{kind: colorBasic, basic: v}, nil
	}
	if m := hexColorRe.FindStringSubmatch(s); m != nil {
		r, _ := strconv.ParseUint(m[1], 16, 8)
		g, _ := strconv.ParseUint(m[2], 16, 8)
		b, _ := strconv.ParseUint(m[3], 16, 8)
		return Color{kind: colorRGB, r: int(r), g: int(g), b: int(b)}, nil
	}
	if m := rgbColorRe.FindStringSubmatch(s); m != nil {
		r, ok1 := parseComponent(m[1])
		g, ok2 := parseComponent(m[2])
		b, ok3 := parseComponent(m[3])
		if !ok1 || !ok2 || !ok3 {
			return Color{}, errInvalidColor
		}
		return Color{kind: colorRGB, r: r, g: g, b: b}, nil
	}
	if decimalRe.MatchString(s) || hexNumberRe.MatchString(s) {
		v, ok := parseComponent(s)
		if !ok {
			return Color{}, errInvalidColor
		}
		return Color{kind: colorPalette, palette: v}, nil
	}
	return Color{}, errInvalidColor
}

// UnmarshalYAML decodes a color from a YAML scalar.
func (c *Color) UnmarshalYAML(unmarshal func(interface{}) error) error {
	var s string
	if err := unmarshal(&s); err != nil {
		return err
	}
	parsed, err := ParseColor(s)
	if err != nil {
		return err
	}
	*c = parsed
	return nil
}

// IsZero reports whether the color is unset.
func (c Color) IsZero() bool { return c.kind == colorNone }

// fg returns the SGR parameters for using the color as a foreground.
func (c Color) fg() string {
	switch c.kind {
	case colorBasic:
		if c.basic < 8 {
			return strconv.Itoa(30 + c.basic)
		}
		return strconv.Itoa(90 + c.basic - 8)
	case colorPalette:
		return "38;5;" + strconv.Itoa(c.palette)
	case colorRGB:
		return "38;2;" + strconv.Itoa(c.r) + ";" + strconv.Itoa(c.g) + ";" + strconv.Itoa(c.b)
	}
	return ""
}

// bg returns the SGR parameters for using the color as a background.
func (c Color) bg() string {
	switch c.kind {
	case colorBasic:
		if c.basic < 8 {
			return strconv.Itoa(40 + c.basic)
		}
		return strconv.Itoa(100 + c.basic - 8)
	case colorPalette:
		return "48;5;" + strconv.Itoa(c.palette)
	case colorRGB:
		return "48;2;" + strconv.Itoa(c.r) + ";" + strconv.Itoa(c.g) + ";" + strconv.Itoa(c.b)
	}
	return ""
}

func sgr(params ...string) string {
	var b strings.Builder
	for _, p := range params {
		if p == "" {
			continue
		}
		b.WriteString("\x1b[")
		b.WriteString(p)
		b.WriteString("m")
	}
	return b.String()
}
