			Foreground: colorp("cyan"),
		},
		LineStyle: &Style{
			Foreground: colorp("magenta"),
		},
		LeaveTestPrefix: boolp(false),
	}
}

func mergeBool(dst **bool, src *bool) {
	if src != nil {
		*dst = src
	}
}

func mergeColor(dst **Color, src *Color) {
	if src != nil {
		*dst = src
	}
}

func mergeStyle(dst **Style, src *Style) {
	if src == nil {
		return
	}
	if *dst == nil {
		*dst = &Style{}
	}
	d := *dst
	mergeBool(&d.Hide, src.Hide)
	mergeBool(&d.Bold, src.Bold)
	mergeBool(&d.Faint, src.Faint)
	mergeBool(&d.Italic, src.Italic)
	mergeBool(&d.Underline, src.Underline)
	mergeBool(&d.BlinkSlow, src.BlinkSlow)
	mergeBool(&d.BlinkRapid, src.BlinkRapid)
	mergeBool(&d.Inverse, src.Inverse)
	mergeBool(&d.Conceal, src.Conceal)
	mergeBool(&d.CrossOut, src.CrossOut)
	mergeBool(&d.Frame, src.Frame)
	mergeBool(&d.Encircle, src.Encircle)
	mergeBool(&d.Overline, src.Overline)
	mergeColor(&d.Foreground, src.Foreground)
	mergeColor(&d.Background, src.Background)
}

// Merge overlays the values set in src onto c.
func (c *Config) Merge(src *Config) {
	if src == nil {
		return
	}
	if src.LabelType != nil {
		c.LabelType = src.LabelType
	}
	mergeStyle(&c.BuildStyle, src.BuildStyle)
	mergeStyle(&c.StartStyle, src.StartStyle)
	mergeStyle(&c.PassStyle, src.PassStyle)
	mergeStyle(&c.FailStyle, src.FailStyle)
	mergeStyle(&c.SkipStyle, src.SkipStyle)
	mergeStyle(&c.PassPackageStyle, src.PassPackageStyle)
	mergeStyle(&c.FailPackageStyle, src.FailPackageStyle)
	if src.CoverThreshold != nil {
		c.CoverThreshold = src.CoverThreshold
	}
	mergeStyle(&c.CoveredStyle, src.CoveredStyle)
	mergeStyle(&c.UncoveredStyle, src.UncoveredStyle)
	mergeStyle(&c.FileStyle, src.FileStyle)
	mergeStyle(&c.LineStyle, src.LineStyle)
	c.Removals = append(c.Removals, src.Removals...)
	if src.LeaveTestPrefix != nil {
		c.LeaveTestPrefix = src.LeaveTestPrefix
	}
}

func isSet(b *bool) bool { return b != nil && *b }

// Hidden reports whether lines in this style should be dropped.
func (s *Style) Hidden() bool {
	return s != nil && isSet(s.Hide)
}

// Open returns the escape sequences that start the style.
func (s *Style) Open() string {
	if s == nil {
		return ""
	}
	var params []string
	if s.Background != nil && !s.Background.IsZero() {
		params = append(params, s.Background.bg())
	}
	if s.Foreground != nil && !s.Foreground.IsZero() {
		params = append(params, s.Foreground.fg())
	}
	attrs := []struct {
		on   *bool
		code string
	}{
		{s.Bold, "1"},
		{s.Faint, "2"},
		{s.Italic, "3"},
		{s.Underline, "4"},
		{s.BlinkSlow, "5"},
		{s.BlinkRapid, "6"},
		{s.Inverse, "7"},
		{s.Conceal, "8"},
		{s.CrossOut, "9"},
		{s.Frame, "51"},
		{s.Encircle, "52"},
		{s.Overline, "53"},
	}
	for _, a := range attrs {
		if isSet(a.on) {
			params = append(params, a.code)
		}
	}
	return sgr(params...)
}

// Apply decorates text with the style. Hidden styles produce no output and
// styles without any decoration return the text unchanged.
func (s *Style) Apply(text string) string {
	if s.Hidden() {
		return ""
	}
	open := s.Open()
	if open == "" {
		return text
	}
	return open + text + "\x1b[0m"
}

// Unhidden returns a copy of the style with the hide flag cleared.
func (s *Style) Unhidden() *Style {
	if s == nil {
		return nil
	}
	c := *s
	c.Hide = nil
	return &c
}
