package config

import (
	"go/build"
	"log"
	"os"
	"path/filepath"
	"runtime"

	"richgo-reimpl/internal/yaml"
)

var fileNames = []string{".richstyle", ".richstyle.yaml", ".richstyle.yml"}

// Load reads the preference files and merges them over the defaults.
// Problems are reported through the standard logger and otherwise ignored.
func Load() *Config {
	cfg := Default()
	var dirs []string
	if wd, err := os.Getwd(); err == nil {
		dirs = append(dirs, wd)
	}
	if os.Getenv("RICHGO_LOCAL") != "1" {
		if gopath := build.Default.GOPATH; gopath != "" {
			dirs = append(dirs, gopath)
		}
		if goroot := runtime.GOROOT(); goroot != "" {
			dirs = append(dirs, goroot)
		}
		if home, err := os.UserHomeDir(); err == nil && home != "" {
			dirs = append(dirs, home)
		}
	}
	for _, dir := range dirs {
		for _, name := range fileNames {
			path := filepath.Join(dir, name)
			if _, err := os.Stat(path); err != nil {
				continue
			}
			data, err := os.ReadFile(path)
			if err != nil {
				log.Println("error reading from", path, ": ", err)
				continue
			}
			var loaded Config
			if err := yaml.Unmarshal(data, &loaded); err != nil {
				log.Println("error unmarshaling yaml from", path, ": ", err)
				continue
			}
			cfg.Merge(&loaded)
		}
	}
	return cfg
}
EOF
