package editor

import (
	"fmt"
	"regexp"
	"strconv"
	"strings"

	"richgo-reimpl/internal/config"
)

// Patterns used to recognize the different kinds of `go test` output lines.
// They are applied to a line that still carries its trailing newline, in
// multi-line mode, so a match may or may not swallow the terminator.
var (
	reFileLine  = regexp.MustCompile(`([^\s:]+\.go):(\d+(?::\d+)?)`)
	reRun       = regexp.MustCompile(`(?m)^=== RUN   Test.*$`)
	reResult    = regexp.MustCompile(`(?m)^[ \t]*--- (PASS|FAIL|SKIP): Test.*$`)
	reResultCut = regexp.MustCompile(`^--- (?:PASS|FAIL|SKIP): Test`)
	reResultCutKeep = regexp.MustCompile(`^--- (?:PASS|FAIL|SKIP): `)
	reRunCut    = regexp.MustCompile(`^=== RUN   Test`)
	reRunCutKeep = regexp.MustCompile(`^=== RUN   `)
	reOK        = regexp.MustCompile(`(?m)^ok[ \t]+([^ \t]+)(?:[ \t]+(?:[\d.]+\w+|\(cached\)))?[ \t]*(coverage: \d+\.\d+% of statements)?[ \t]*(?:\[no tests to run\])?$`)
	reFailPkg   = regexp.MustCompile(`(?m)^FAIL[ \t]+[^ \t]+[ \t]+(?:[\d.]+\w+|\[build failed\])$`)
	reNoTest    = regexp.MustCompile(`(?m)^\?[ \t]+([^ \t]+[ \t]+\[no test files\])$`)
	reBuild     = regexp.MustCompile(`(?m)^# ([^ ]*)(?: \[[^ ]+\])?$`)
	reCoverage  = regexp.MustCompile(`(?m)^coverage: (\d+\.\d)% of statements$`)
	rePassPkg   = regexp.MustCompile(`(?m)^PASS[ \t]*$`)
	reFailPkgLn = regexp.MustCompile(`(?m)^FAIL[ \t]*$`)
	reLeadSpace = regexp.MustCompile(`^ +`)
)

// Test is the LineEditor that decorates `go test` output.
type Test struct {
	cfg      *config.Config
	removals []*regexp.Regexp
	current  *config.Style
}

// NewTest builds the editor for the given preferences.
func NewTest(cfg *config.Config) *Test {
	t := &Test{cfg: cfg}
	for _, r := range cfg.Removals {
		t.removals = append(t.removals, regexp.MustCompile(r))
	}
	return t
}

func (t *Test) labelType() config.LabelType {
	if t.cfg.LabelType == nil {
		return config.LabelNone
	}
	return *t.cfg.LabelType
}

func (t *Test) label(long, short string) string {
	switch t.labelType() {
	case config.LabelLong:
		return fmt.Sprintf("%-5s| ", long)
	case config.LabelShort:
		return fmt.Sprintf("%-2s ", short)
	}
	return ""
}

func (t *Test) leaveTestPrefix() bool {
	return t.cfg.LeaveTestPrefix != nil && *t.cfg.LeaveTestPrefix
}

func (t *Test) coverThreshold() int {
	if t.cfg.CoverThreshold == nil {
		return 0
	}
	return *t.cfg.CoverThreshold
}

func (t *Test) removeAll(s string) string {
	for _, r := range t.removals {
		s = r.ReplaceAllString(s, "")
	}
	return s
}

func indentFor(name string) string {
	return strings.Repeat("  ", strings.Count(name, "/"))
}

// highlight decorates file:line references, re-opening the current style
// after each of them.
func (t *Test) highlight(text string) string {
	reopen := t.current.Open()
	return reFileLine.ReplaceAllStringFunc(text, func(m string) string {
		sub := reFileLine.FindStringSubmatch(m)
		return t.cfg.FileStyle.Apply(sub[1]) + t.cfg.LineStyle.Apply(":"+sub[2]) + reopen
	})
}

// Edit implements LineEditor.
func (t *Test) Edit(line string) string {
	text := t.highlight(line + "\n")

	var out string
	typed := true
	switch {
	case reRun.MatchString(text):
		loc := reRun.FindStringIndex(text)
		body := text[loc[0]:loc[1]]
		cut := reRunCut
		if t.leaveTestPrefix() {
			cut = reRunCutKeep
		}
		content := indentFor(body) + cut.ReplaceAllString(body, "")
		style := t.cfg.StartStyle
		t.current = style.Unhidden()
		out = style.Apply(t.label("START", ">")+content) + text[loc[1]:]

	case reResult.MatchString(text):
		loc := reResult.FindStringIndex(text)
		body := text[loc[0]:loc[1]]
		kind := reResult.FindStringSubmatch(body)[1]
		var style *config.Style
		var long, short string
		switch kind {
		case "PASS":
			style, long, short = t.cfg.PassStyle, "PASS", "o"
		case "FAIL":
			style, long, short = t.cfg.FailStyle, "FAIL", "x"
		default:
			style, long, short = t.cfg.SkipStyle, "SKIP", "-"
		}
		cut := reResultCut
		if t.leaveTestPrefix() {
			cut = reResultCutKeep
		}
		content := reLeadSpace.ReplaceAllString(body, "")
		content = indentFor(body) + cut.ReplaceAllString(content, "")
		t.current = style
		out = style.Apply(t.label(long, short)+content) + text[loc[1]:]

	case reOK.MatchString(text):
		loc := reOK.FindStringSubmatchIndex(text)
		pkg := text[loc[2]:loc[3]]
		cover := ""
		if loc[4] >= 0 {
			cover = text[loc[4]:loc[5]]
		}
		style := t.cfg.PassStyle
		t.current = style
		out = style.Apply(t.label("PASS", "o")+pkg+" "+cover) + text[loc[1]:]

	case reFailPkg.MatchString(text):
		loc := reFailPkg.FindStringIndex(text)
		body := text[loc[0]:loc[1]]
		style := t.cfg.FailStyle
		t.current = style
		out = style.Apply(t.label("FAIL", "x")+strings.TrimPrefix(body, "FAIL")) + text[loc[1]:]

	case reNoTest.MatchString(text):
		loc := reNoTest.FindStringSubmatchIndex(text)
		style := t.cfg.SkipStyle
		t.current = style
		out = style.Apply(t.label("SKIP", "-")+text[loc[2]:loc[3]]) + text[loc[1]:]

	case reBuild.MatchString(text):
		loc := reBuild.FindStringIndex(text)
		body := text[loc[0]:loc[1]]
		style := t.cfg.BuildStyle
		t.current = style
		out = style.Apply(t.label("BUILD", "!!")+strings.TrimPrefix(body, "# ")) + text[loc[1]:]

	case reCoverage.MatchString(text):
		loc := reCoverage.FindStringSubmatchIndex(text)
		pct := text[loc[2]:loc[3]]
		value, _ := strconv.ParseFloat(pct, 64)
		style := t.cfg.UncoveredStyle
		if int(value) >= t.coverThreshold() {
			style = t.cfg.CoveredStyle
		}
		filled := int(value / 10)
		bar := strings.Repeat("#", filled) + strings.Repeat("_", 10-filled)
		out = style.Apply(t.label("COVER", "%")+pct+"% ["+bar+"]") + text[loc[1]:]

	case rePassPkg.MatchString(text):
		loc := rePassPkg.FindStringIndex(text)
		out = t.cfg.PassPackageStyle.Apply("PASS") + text[loc[1]:]

	case reFailPkgLn.MatchString(text):
		loc := reFailPkgLn.FindStringIndex(text)
		out = t.cfg.FailPackageStyle.Apply("FAIL") + text[loc[1]:]

	default:
		typed = false
		out = text
	}

	out = t.removeAll(out)
	if out == "" || out == "\n" {
		return ""
	}
	if typed {
		return out
	}
	label := t.label("", "")
	if strings.HasSuffix(out, "\n") {
		return t.current.Apply(label+out[:len(out)-1]) + "\n"
	}
	return t.current.Apply(label + out)
}
EOF
