		return t.cfg.FileStyle.Apply(sub[1]) + t.cfg.LineStyle.Apply(":"+sub[2]) + reopen
	})
}

// Edit implements LineEditor.
func (t *Test) Edit(line string) string {
	text := t.highlight(line + "\n")

	var out string
	typed := true
	switch {
	case reRun.MatchString(text):
		loc := reRun.FindStringIndex(text)
		body := text[loc[0]:loc[1]]
		cut := reRunCut
		if t.leaveTestPrefix() {
			cut = reRunCutKeep
		}
		content := indentFor(body) + cut.ReplaceAllString(body, "")
		style := t.cfg.StartStyle
		t.current = style.Unhidden()
		out = style.Apply(t.label("START", ">")+content) + text[loc[1]:]

	case reResult.MatchString(text):
		loc := reResult.FindStringIndex(text)
		body := text[loc[0]:loc[1]]
		kind := reResult.FindStringSubmatch(body)[1]
		var style *config.Style
		var long, short string
		switch kind {
		case "PASS":
			style, long, short = t.cfg.PassStyle, "PASS", "o"
		case "FAIL":
			style, long, short = t.cfg.FailStyle, "FAIL", "x"
		default:
			style, long, short = t.cfg.SkipStyle, "SKIP", "-"
		}
		cut := reResultCut
		if t.leaveTestPrefix() {
			cut = reResultCutKeep
		}
		content := reLeadSpace.ReplaceAllString(body, "")
		content = indentFor(body) + cut.ReplaceAllString(content, "")
		t.current = style
		out = style.Apply(t.label(long, short)+content) + text[loc[1]:]

	case reOK.MatchString(text):
		loc := reOK.FindStringSubmatchIndex(text)
		pkg := text[loc[2]:loc[3]]
		cover := ""
		if loc[4] >= 0 {
			cover = text[loc[4]:loc[5]]
		}
		style := t.cfg.PassStyle
		t.current = style
		out = style.Apply(t.label("PASS", "o")+pkg+" "+cover) + text[loc[1]:]

	case reFailPkg.MatchString(text):
		loc := reFailPkg.FindStringIndex(text)
		body := text[loc[0]:loc[1]]
		style := t.cfg.FailStyle
		t.current = style
		out = style.Apply(t.label("FAIL", "x")+strings.TrimPrefix(body, "FAIL")) + text[loc[1]:]

	case reNoTest.MatchString(text):
		loc := reNoTest.FindStringSubmatchIndex(text)
		style := t.cfg.SkipStyle
		t.current = style
		out = style.Apply(t.label("SKIP", "-")+text[loc[2]:loc[3]]) + text[loc[1]:]

	case reBuild.MatchString(text):
		loc := reBuild.FindStringIndex(text)
		body := text[loc[0]:loc[1]]
		style := t.cfg.BuildStyle
		t.current = style
		out = style.Apply(t.label("BUILD", "!!")+strings.TrimPrefix(body, "# ")) + text[loc[1]:]

	case reCoverage.MatchString(text):
		loc := reCoverage.FindStringSubmatchIndex(text)
		pct := text[loc[2]:loc[3]]
		value, _ := strconv.ParseFloat(pct, 64)
		style := t.cfg.UncoveredStyle
		if int(value) >= t.coverThreshold() {
			style = t.cfg.CoveredStyle
		}
		filled := int(value / 10)
		bar := strings.Repeat("#", filled) + strings.Repeat("_", 10-filled)
		out = style.Apply(t.label("COVER", "%")+pct+"% ["+bar+"]") + text[loc[1]:]

	case rePassPkg.MatchString(text):
		loc := rePassPkg.FindStringIndex(text)
		out = t.cfg.PassPackageStyle.Apply("PASS") + text[loc[1]:]

	case reFailPkgLn.MatchString(text):
		loc := reFailPkgLn.FindStringIndex(text)
		out = t.cfg.FailPackageStyle.Apply("FAIL") + text[loc[1]:]

	default:
		typed = false
		out = text
	}

	out = t.removeAll(out)
	if out == "" || out == "\n" {
		return ""
	}
	if typed {
		return out
	}
	label := t.label("", "")
	if strings.HasSuffix(out, "\n") {
		return t.current.Apply(label+out[:len(out)-1]) + "\n"
	}
	return t.current.Apply(label + out)
}
EOF
