func TestDefaultDecoration(t *testing.T) {
	got := edit(t, config.Default(), "=== RUN   TestA/b\n--- PASS: TestA/b (0.00s)\nPASS\nok  \tpkg\t0.1s\n")
	want := "\x1b[90mSTART|   A/b\x1b[0m\n\x1b[32mPASS |   A/b (0.00s)\x1b[0m\n\x1b[32mPASS | pkg \x1b[0m\n"
	if got != want {
		t.Fatalf("got %q, want %q", got, want)
	}
}

func TestContinuationInheritsStyle(t *testing.T) {
	got := edit(t, config.Default(), "--- FAIL: TestA (0.00s)\n    a_test.go:12: boom\n")
	want := "\x1b[31m\x1b[1mFAIL | A (0.00s)\x1b[0m\n" +
		"\x1b[31m\x1b[1m     |     \x1b[36ma_test.go\x1b[0m\x1b[35m:12\x1b[0m\x1b[31m\x1b[1m: boom\x1b[0m\n"
	if got != want {
		t.Fatalf("got %q, want %q", got, want)
	}
}

func TestBuildHeaderKeepsNewlineInside(t *testing.T) {
	got := edit(t, config.Default(), "# pkg\n")
	want := "\x1b[33m\x1b[1mBUILD| pkg\n\x1b[0m"
	if got != want {
		t.Fatalf("got %q, want %q", got, want)
	}
}

func TestEmptyLinesDropped(t *testing.T) {
	if got := edit(t, config.Default(), "a\n\n\nb\n"); got != "     | a\n     | b\n" {
		t.Fatalf("got %q", got)
	}
}

func TestPassthrough(t *testing.T) {
	var sb strings.Builder
	s := NewStream(&sb, Passthrough{})
	s.Write([]byte("a\r\nb"))
	s.Write([]byte("c\n"))
	s.Close()
	if sb.String() != "a\nbc\n\n" {
		t.Fatalf("got %q", sb.String())
	}
}
